<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">systemctl</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --user</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> set-environment</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> http_proxy=http://192.168.31.82:7890</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> https_proxy=http://192.168.31.82:7890</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ALL_PROXY=http://192.168.31.82:7890</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> NO_PROXY=localhost,127.0.0.1</span></span>
